    def __init__(self, width=1920, height=1080, port=9333, extra=None):
        self.port = port
        args = [CHROME, "--headless", "--remote-debugging-port=%d" % port,
                "--window-size=%d,%d" % (width, height), "--hide-scrollbars",
                "--autoplay-policy=no-user-gesture-required",
                "--enable-webgl", "--ignore-gpu-blocklist", "--use-angle=metal",
                "--allow-file-access-from-files", "--no-first-run", "--no-default-browser-check",
                "--user-data-dir=" + os.path.join(os.path.dirname(os.path.abspath(__file__)), "profile")]
        if extra: args += extra
        args.append("about:blank")
        self.proc = subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for _ in range(100):
            try:
                tabs = json.loads(urllib.request.urlopen("http://127.0.0.1:%d/json/list" % port).read())
                pages = [t for t in tabs if t.get("type") == "page"]
                if pages:
                    break
            except Exception:
                pass
            time.sleep(0.1)
        self.ws = WS(pages[0]["webSocketDebuggerUrl"])
        self.mid = 0
        self.events = []
        self.call("Runtime.enable"); self.call("Page.enable"); self.call("Log.enable")
        self.set_size(width, height)

