                    raise RuntimeError(str(msg["error"]))
                return msg.get("result", {})
            self.events.append(msg)
            if time.time() - t0 > timeout:
                raise TimeoutError(method)

    def set_size(self, w, h, dpr=1):
        self.call("Emulation.setDeviceMetricsOverride", {"width": w, "height": h, "deviceScaleFactor": dpr, "mobile": False})

    def eval(self, expr, await_promise=False):
        r = self.call("Runtime.evaluate", {"expression": expr, "returnByValue": True, "awaitPromise": await_promise})
        if "exceptionDetails" in r:
            raise RuntimeError(json.dumps(r["exceptionDetails"])[:2000])
        return r.get("result", {}).get("value")

    def navigate(self, url, wait=3.0):
        self.call("Page.navigate", {"url": url})
        time.sleep(wait)

    def screenshot(self, path):
        r = self.call("Page.captureScreenshot", {"format": "png"})
        with open(path, "wb") as f:
            f.write(base64.b64decode(r["data"]))

    def drain(self):
        # pull pending events without blocking long
        self.ws.sock.settimeout(0.05)
        try:
            while True:
                self.events.append(json.loads(self.ws.recv()))
        except Exception:
            pass
        self.ws.sock.settimeout(None)
        out = []
        for e in self.events:
            m = e.get("method")
            if m == "Runtime.consoleAPICalled":
                args = e["params"].get("args", [])
                out.append("console.%s: %s" % (e["params"].get("type"), " ".join(str(a.get("value", a.get("description", ""))) for a in args)))
            elif m == "Runtime.exceptionThrown":
                d = e["params"]["exceptionDetails"]
                out.append("EXCEPTION: %s %s" % (d.get("text"), json.dumps(d.get("exception", {}).get("description", ""))[:1500]))
            elif m == "Log.entryAdded":
                en = e["params"]["entry"]
                out.append("log.%s: %s %s" % (en.get("level"), en.get("text"), en.get("url", "")))
        self.events = []
        return out

    def close(self):
        try:
            self.call("Browser.close", timeout=5)
        except Exception:
            pass
        try:
            self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()

