import sys, os, time, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser
here = os.path.dirname(os.path.abspath(__file__))
os.system("python3 %s/mkdbg.py" % here)
W = int(os.environ.get("W", 1280)); H = int(os.environ.get("H", 720))
b = Browser(W, H, port=9335)
b.navigate("file://" + os.path.join(here, "dbg.html"), wait=4)
for l in b.drain(): print(l)
# views: (name, carId, simTime, camLocal[x,y,z], targetLocal[x,y,z], fov)
views = json.loads(sys.argv[1]) if len(sys.argv) > 1 else [
    ["front34", 1, 1.0, [4.5, 1.6, 3.5], [0, 0.35, 0], 35],
    ["side", 1, 1.0, [0.0, 0.8, 7.0], [0, 0.35, 0], 40],
    ["rear34", 1, 1.0, [-5.0, 1.5, -3.0], [0, 0.4, 0], 35],
    ["top", 1, 1.0, [0.5, 7.5, 0.01], [0, 0, 0], 45],
    ["frontlow", 0, 1.0, [5.0, 0.5, 1.2], [0, 0.3, 0], 35],
]
for name, cid, t, cl, tl, fov in views:
    js = """(function(){ const D = window.__dbg; D.renderAt(%f); const car = D.CARS[%d];
      car.root.updateMatrixWorld(true);
      const p = new D.THREE.Vector3(%f,%f,%f).applyMatrix4(car.root.matrixWorld);
      const q = new D.THREE.Vector3(%f,%f,%f).applyMatrix4(car.root.matrixWorld);
      D.camera.position.copy(p); D.camera.up.set(0,1,0); D.camera.lookAt(q); D.camera.fov = %f; D.camera.updateProjectionMatrix(); D.camera.updateMatrixWorld();
      D.renderer.render(D.scene, D.camera); return car.meshCount; })()""" % (t, cid, cl[0], cl[1], cl[2], tl[0], tl[1], tl[2], fov)
    mc = b.eval(js)
    time.sleep(0.3)
    b.screenshot(os.path.join(here, "car_%s.png" % name))
    print(name, "meshCount", mc)
for l in b.drain(): print(l)
b.close()

