    const fx = (x % cell) / cell, fy = (y % cell) / cell;
    const horiz = ((cx + cy) & 3) < 2;
    const across = horiz ? fy : fx;
    const tow = Math.sin(across * Math.PI);
    const fib = 0.5 + 0.5 * Math.sin((horiz ? fx : fy) * Math.PI * 14 + hash2(cx, cy) * 6);
