const MAT = {};
MAT.road = stdMat({ map: TEX.asphalt, roughnessMap: TEX.asphaltRough, bumpMap: TEX.asphaltBump, bumpScale: 0.0022,
  roughness: 1.0, metalness: 0.0, vertexColors: true, envMap: ENV, envMapIntensity: 0.32 });
MAT.road.map.repeat.set(1, 1);
MAT.line = stdMat({ color: lin(0xc9cdd1), roughness: 0.32, metalness: 0, envMap: ENV, envMapIntensity: 0.12, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4 });
MAT.kerb = stdMat({ map: TEX.kerb, roughness: 0.32, metalness: 0, envMap: ENV, envMapIntensity: 0.3, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -2 });
MAT.checker = stdMat({ map: TEX.checker, roughness: 0.3, envMap: ENV, envMapIntensity: 0.25, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -4 });
MAT.barrier = stdMat({ map: TEX.barrier, roughness: 0.48, metalness: 0.35, envMap: ENV, envMapIntensity: 0.35 });
MAT.fence = stdMat({ map: TEX.fence, color: lin(0x9aa3ad), transparent: true, opacity: 0.42, side: THREE.DoubleSide, depthWrite: false,
  roughness: 0.4, metalness: 0.7, envMap: ENV, envMapIntensity: 0.4 });
MAT.galv = stdMat({ color: lin(0x8a939c), roughness: 0.45, metalness: 0.7, envMap: ENV, envMapIntensity: 0.35 });
MAT.darkMetal = stdMat({ color: lin(0x22262c), roughness: 0.55, metalness: 0.6, envMap: ENV, envMapIntensity: 0.3 });
MAT.concrete = stdMat({ color: lin(0x6b6f74), roughness: 0.9, metalness: 0 });
MAT.terrain = stdMat({ vertexColors: true, roughness: 0.97, metalness: 0 });
MAT.tree = stdMat({ color: lin(0x0b140d), roughness: 1.0 });
MAT.crowd = stdMat({ roughness: 0.85 });
MAT.lampPanel = new THREE.MeshBasicMaterial({ map: TEX.lampPanel, color: new THREE.Color(3.2, 3.4, 3.7) });
MAT.standLight = new THREE.MeshBasicMaterial({ color: new THREE.Color(2.6, 2.3, 1.8) });
MAT.garage = stdMat({ map: TEX.garage, emissiveMap: TEX.garage, emissive: new THREE.Color(1, 1, 1), emissiveIntensity: 0.45, roughness: 0.8 });
MAT.screen = new THREE.MeshBasicMaterial({ color: new THREE.Color(0.25, 0.45, 0.9) });
TEX.fence.repeat.set(3, 3);

const SHADOW_RECEIVERS = [];
function addMesh(geo, mat, opts) {
  const m = new THREE.Mesh(geo, mat);
  m.receiveShadow = !!(opts && opts.receive);
  m.castShadow = !!(opts && opts.cast);
  if (opts && opts.order !== undefined) m.renderOrder = opts.order;
  scene.add(m);
  return m;
}

(function buildRoad() {
  const prof = [[-9.6, -0.005], [-7.0, 0], [-3.5, 0], [0, 0], [3.5, 0], [7.0, 0], [9.6, -0.005]];
  const g = sweep(0, L, 1.0, prof, {
    uLen: 10,
    color: (s, d) => {
      const ad = Math.abs(d);
      if (ad > 7.01) return [0.80, 0.84, 0.88];                 // paved run-off apron
      const line = 1 - 0.10 * Math.exp(-Math.pow((d + 1.4 * Math.sin(s / 90)) / 2.2, 2));   // darker rubbered line
      return [line, line, line];
    }
  });
  addMesh(g, MAT.road, { receive: true });
  // pit lane surface
  addMesh(sweep(PIT_S0, PIT_S1, 2.0, [[9.6, -0.01], [23.0, -0.01]], { uLen: 10, color: () => [0.9, 0.9, 0.92] }), MAT.road, { receive: true });
  // white edge lines
  addMesh(mergeGeos([sweep(0, L, 1.0, [[6.72, 0.004], [6.92, 0.004]]), sweep(0, L, 1.0, [[-6.92, 0.004], [-6.72, 0.004]])]), MAT.line, { receive: true });
  // chequered start/finish line at s = 0

