// Car paint/carbon additionally receive a soft cool key light that travels with the action
// (a car-only "follow" light, so the road away from the pools stays dark).
const KEY_UNIFORMS = { uKeyDirV: { value: new THREE.Vector3(0, 1, 0) }, uKeyCol: { value: new THREE.Vector3(0.42, 0.47, 0.56) } };
const KEY_CODE = ['#if defined( RE_Direct )', '{', '  directLight.color = uKeyCol;', '  directLight.direction = uKeyDirV;', '  directLight.visible = true;',
  '  RE_Direct( directLight, geometry, material, reflectedLight );', '}', '#endif', ''].join('\n');
function patchCar(mat) {
  mat.onBeforeCompile = function (shader) {
    shader.uniforms.uLampPosV = LAMP_UNIFORMS.uLampPosV;
    shader.uniforms.uLampDirV = LAMP_UNIFORMS.uLampDirV;
    shader.uniforms.uLampCol = LAMP_UNIFORMS.uLampCol;
    shader.uniforms.uKeyDirV = KEY_UNIFORMS.uKeyDirV;
    shader.uniforms.uKeyCol = KEY_UNIFORMS.uKeyCol;
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>' + LAMP_DECL + 'uniform vec3 uKeyDirV;\nuniform vec3 uKeyCol;\n')
      .replace('#include <lights_fragment_begin>', '#include <lights_fragment_begin>\n' + LAMP_LOOP + KEY_CODE);
  };
  return mat;
}
const carStd = (p) => patchCar(new THREE.MeshStandardMaterial(p));
const carPhys = (p) => patchCar(new THREE.MeshPhysicalMaterial(p));

