(function buildBarriersAndFence() {
  const inner = [[9.0, -0.35], [9.0, 0.85]], top = [[9.0, 0.85], [9.32, 0.85]], outer = [[9.32, 0.85], [9.32, -0.35]];
  const geos = [];
  const addSide = (s0, s1, side) => {
    for (const p of [inner, top, outer]) geos.push(sweep(s0, s1, 2.0, side > 0 ? p : mirrorProfile(p), { uLen: 4, vAbs: 1.2 }));
  };
  addSide(0, L, -1);
  addSide(PIT_S1, L + PIT_S0, 1);
  addMesh(mergeGeos(geos), MAT.barrier, { receive: true });
  // pit wall (concrete, taller) on the +Z side of the main straight
  const pw = [];
  for (const p of [[[9.0, -0.3], [9.0, 1.15]], [[9.0, 1.15], [9.6, 1.15]], [[9.6, 1.15], [9.6, -0.3]]]) pw.push(sweep(PIT_S0, PIT_S1, 2.0, p, { uLen: 4, vAbs: 1.5 }));
  addMesh(mergeGeos(pw), MAT.barrier, { receive: true });
  // catch fencing (transparent wire mesh) on both sides, leaning slightly inwards
  const fg = [];
  for (const side of [-1, 1]) {
    const yb = 0.85;
    const segs = side > 0 ? [[0, PIT_S1 - L], [PIT_S1, L + PIT_S0]] : [[0, L]];
    for (const [a, b] of segs) {
      if (b <= a) continue;
      const pr = [[9.18, yb], [9.05, 4.1]];
      fg.push(sweep(a, b, 2.0, side > 0 ? pr : mirrorProfile(pr), { uLen: 1.0, vAbs: 1.0 }));
    }
    const prp = [[9.35, 1.15], [9.25, 4.2]];
    if (side > 0) fg.push(sweep(PIT_S0, PIT_S1, 2.0, prp, { uLen: 1.0, vAbs: 1.0 }));
  }
  const fence = addMesh(mergeGeos(fg), MAT.fence, { order: 1 });
  fence.frustumCulled = false;
  // fence posts + top rail
  const postGeo = new THREE.CylinderGeometry(0.045, 0.055, 3.4, 6);

