const fg = [];
// photographer / broadcast-camera holes in the fencing in front of the fixed trackside cameras
const HOLES = [[400, -1], [725, 1], [1300, -1], [-20, 1]];
const cutHoles = (a, b, side) => {
  let parts = [[a, b]];
  for (const [hs, hside] of HOLES) {
    if (hside !== side) continue;
    for (const c of [hs, hs + L, hs - L]) {
      const next = [];
      for (const [p, q] of parts) {
        const h0 = c - 14, h1 = c + 14;
        if (h1 <= p || h0 >= q) { next.push([p, q]); continue; }
        if (h0 > p) next.push([p, h0]);
        if (h1 < q) next.push([h1, q]);
      }
      parts = next;
    }
  }
  return parts;
};
for (const side of [-1, 1]) {
  const yb = 0.85;
  const segs = side > 0 ? [[PIT_S1, L + PIT_S0]] : [[0, L]];
  for (const [a0, b0] of segs) for (const [a, b] of cutHoles(a0, b0, side)) {
    if (b - a < 1) continue;
    const pr = [[9.18, yb], [9.05, 4.1]];
    fg.push(sweep(a, b, 2.0, side > 0 ? pr : mirrorProfile(pr), { uLen: 1.0, vAbs: 1.0 }));
  }
  const prp = [[9.35, 1.15], [9.25, 4.2]];
  if (side > 0) for (const [a, b] of cutHoles(PIT_S0, PIT_S1, 1)) if (b - a >= 1) fg.push(sweep(a, b, 2.0, prp, { uLen: 1.0, vAbs: 1.0 }));
}

