import sys, os, time, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser
here = os.path.dirname(os.path.abspath(__file__))
os.system("python3 %s/mkdbg.py > /dev/null" % here)
b = Browser(1280, 720, port=9338)
b.navigate("file://" + os.path.join(here, "dbg.html"), wait=1.0)
for _ in range(50):
    st = b.eval("window.__dbg ? window.__dbg.state : 'none'")
    if st == 'PLAYING': break
    time.sleep(0.1)
print("state", st, "ctx", b.eval("window.__dbg.Sound._ctx.state"))
b.eval("""(function(){ const S = window.__dbg.Sound; const a = S._ctx.createAnalyser(); a.fftSize = 4096; S._master.connect(a); window.__an = a;
  const a2 = S._ctx.createAnalyser(); a2.fftSize = 4096; S._mix.connect(a2); window.__an2 = a2; return 1; })()""")
b.eval("document.querySelectorAll('.speed-pill')[3].click()")  # 2x
rows = []
for i in range(44):
    r = b.eval("""(function(){ const a = window.__an, a2 = window.__an2; const d = new Float32Array(a.fftSize); a.getFloatTimeDomainData(d);
      let pk = 0, rms = 0; for (const v of d) { pk = Math.max(pk, Math.abs(v)); rms += v*v; } rms = Math.sqrt(rms / d.length);
      const d2 = new Float32Array(a2.fftSize); a2.getFloatTimeDomainData(d2); let pk2 = 0; for (const v of d2) pk2 = Math.max(pk2, Math.abs(v));
      const f = new Float32Array(a.frequencyBinCount); a.getFloatFrequencyData(f); let best = 0, bi = 0; for (let i = 5; i < f.length; i++) if (f[i] > f[best] || best === 0) { best = i; }
      return [ +window.__dbg.simTime.toFixed(2), window.__dbg.state, +pk.toFixed(3), +rms.toFixed(4), +pk2.toFixed(3), Math.round(best * a.context.sampleRate / a.fftSize), window.__dbg.CAM.shot ]; })()""")
    rows.append(r)
    time.sleep(0.5)
for r in rows: print(r)
b.eval("document.getElementById('btn-toggle').click()")
time.sleep(0.15)
print("after pause:", b.eval("(function(){ const a = window.__an; const d = new Float32Array(a.fftSize); a.getFloatTimeDomainData(d); let pk=0; for (const v of d) pk=Math.max(pk,Math.abs(v)); return [window.__dbg.state, pk]; })()"))
for l in b.drain(): print(l)
b.close()

