for (const side of [-1, 1]) for (let i = 0; i < Math.floor(L / 4); i++) {
  const s = i * 4;
  trackAt(s, TS);
  const pit = side > 0 && inPitZone(s);
  const d = side * (pit ? 9.3 : 9.12), yb = pit ? 1.15 : 0.85;
  dm.position.set(TS.px + TS.nx * d, TS.py + yb + 1.6, TS.pz + TS.nz * d);
  dm.rotation.set(0, 0, 0); dm.updateMatrix();
  posts.setMatrixAt(c++, dm.matrix);
}

