sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from cdp import Browser
here = os.path.dirname(os.path.abspath(__file__))
os.system("python3 %s/mkdbg.py > /dev/null" % here)
b = Browser(1920, 1080, port=9340)
b.set_size(1920, 1080, dpr=2)
b.navigate("file://" + os.path.join(here, "dbg.html"), wait=3.0)
b.eval("(function(){const s=document.getElementById('scrubber'); s.value='0'; s.dispatchEvent(new Event('input',{bubbles:true})); return 1;})()")
print(b.eval("(function(){ const gl=window.__dbg.renderer.getContext(); return !!gl.getExtension('EXT_disjoint_timer_query_webgl2'); })()"))
js = r"""
(async function(){
  const D = window.__dbg, gl = D.renderer.getContext(), ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
  function sleep(ms){ return new Promise(r=>setTimeout(r,ms)); }
  async function gpuTime(t, n){
    const res = [];
    for (let i=0;i<n;i++){
      const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
      D.renderAt(t);
      gl.endQuery(ext.TIME_ELAPSED_EXT);
      let tries = 0; while (!gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE) && tries < 200) { await sleep(5); tries++; }
      res.push(gl.getQueryParameter(q, gl.QUERY_RESULT) / 1e6); gl.deleteQuery(q);
    }
    res.sort((a,b)=>a-b); return +res[Math.floor(n/2)].toFixed(2);
  }
  const out = {};
  const find = (pred) => { const r=[]; D.scene.traverse(o=>{ if (pred(o)) r.push(o); }); return r; };
  const fence = find(o=>o.isMesh && o.material && o.material.map && o.material.transparent && o.renderOrder===1);
  const parts = find(o=>o.isPoints || o.isLineSegments);
  const cones = find(o=>o.isMesh && o.renderOrder===3);
  for (const t of [2.0, 6.0, 13.0, 17.0, 36.6]) {
    const r = {};
    r.base = await gpuTime(t, 7);
    fence.forEach(o=>o.visible=false); r.noFence = await gpuTime(t, 7); fence.forEach(o=>o.visible=true);
    parts.forEach(o=>o.visible=false); r.noParticles = await gpuTime(t, 7); parts.forEach(o=>o.visible=true);
    cones.forEach(o=>o.visible=false); r.noCones = await gpuTime(t, 7); cones.forEach(o=>o.visible=true);
    D.renderer.shadowMap.autoUpdate = false; r.noShadowUpdate = await gpuTime(t, 7); D.renderer.shadowMap.autoUpdate = true;
    out[t] = r;
  }
  return out;
})()
"""
r = b.eval(js, await_promise=True)
for k, v in r.items(): print(k, v)
for l in b.drain(): print(l)
b.close()

